import React, { useState } from 'react';
import { Menu, X, LayoutDashboard, Sun, Moon } from 'lucide-react';
import academyLogo from '../assets/logovighnaviacademy.png';

export default function Navbar({ activeScreen, setActiveScreen, theme, toggleTheme }) {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const isDark = theme === 'dark';

  const navLinks = [
    { name: 'Home', screen: 'home' },
    { name: 'Career Guidance', screen: 'guidance' },
    { name: 'Workshops', screen: 'workshops' },
    { name: 'Courses', screen: 'courses' },
    { name: 'Internships', screen: 'internships' },
    { name: 'B.Tech Projects', screen: 'btech-projects' },
    { name: 'M.Tech Projects', screen: 'mtech-projects' },
    { name: 'About', screen: 'about' },
    { name: 'Contact', screen: 'contact' },
  ];

  const handleNav = (screen) => {
    setActiveScreen(screen);
    setMobileMenuOpen(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <nav className="sticky top-0 z-40 w-full transition-colors duration-200 bg-white/95 dark:bg-black/95 backdrop-blur-md border-b border-neutral-200 dark:border-neutral-800 text-black dark:text-white">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
        
        {/* Brand / Logo */}
        <div 
          onClick={() => handleNav('home')} 
          className="cursor-pointer flex items-center space-x-3 group select-none"
        >
          <img
            src={academyLogo}
            alt="Vighnavi Academy Logo"
            className="h-10 w-auto object-contain transition-transform duration-200 group-hover:scale-105"
            onError={(e) => {
              e.currentTarget.style.display = 'none';
            }}
          />
          <div>
            <span className="text-xl font-extrabold tracking-tight text-neutral-900 dark:text-white block leading-tight">
              Vighnavi Academy
            </span>
            <p className="text-[10px] text-neutral-500 dark:text-neutral-400 tracking-wider uppercase font-semibold">
              Technical Excellence
            </p>
          </div>
        </div>

        {/* Desktop Nav Links */}
        <div className="hidden xl:flex items-center space-x-1">
          {navLinks.map((link) => {
            const isActive = activeScreen === link.screen;
            return (
              <button
                key={link.screen}
                onClick={() => handleNav(link.screen)}
                className={`px-3 py-2 rounded-lg text-sm font-semibold transition-colors duration-150 ${
                  isActive
                    ? 'bg-neutral-900 text-white dark:bg-white dark:text-black border border-neutral-900 dark:border-white shadow-sm'
                    : 'text-neutral-700 dark:text-neutral-300 hover:text-black dark:hover:text-white hover:bg-neutral-100 dark:hover:bg-neutral-900'
                }`}
              >
                {link.name}
              </button>
            );
          })}
        </div>

        {/* Desktop Actions: Theme Toggle & Dashboard */}
        <div className="hidden xl:flex items-center space-x-3">
          {/* Global Theme Toggle Button */}
          <button
            onClick={toggleTheme}
            aria-label="Toggle Theme"
            title={isDark ? 'Switch to Light Theme' : 'Switch to Dark Theme'}
            className="flex items-center space-x-2 px-3 py-2 rounded-xl border border-neutral-300 dark:border-neutral-700 bg-neutral-100 dark:bg-neutral-900 text-neutral-900 dark:text-white hover:bg-neutral-200 dark:hover:bg-neutral-800 transition"
          >
            {isDark ? (
              <>
                <Sun className="w-4 h-4 text-white" />
                <span className="text-xs font-bold">Light</span>
              </>
            ) : (
              <>
                <Moon className="w-4 h-4 text-black" />
                <span className="text-xs font-bold">Dark</span>
              </>
            )}
          </button>

          {/* Student Dashboard Button */}
          <button
            onClick={() => handleNav('dashboard')}
            className="flex items-center space-x-2 bg-neutral-900 hover:bg-neutral-800 dark:bg-white dark:hover:bg-neutral-200 text-white dark:text-black px-4 py-2 rounded-xl font-bold text-sm border border-neutral-900 dark:border-white transition-all transform active:scale-95 shadow-sm"
          >
            <LayoutDashboard className="w-4 h-4" />
            <span>Dashboard</span>
          </button>
        </div>

        {/* Mobile Action Buttons */}
        <div className="xl:hidden flex items-center space-x-2">
          <button
            onClick={toggleTheme}
            aria-label="Toggle Theme"
            className="p-2 rounded-lg border border-neutral-300 dark:border-neutral-700 bg-neutral-100 dark:bg-neutral-900 text-neutral-900 dark:text-white"
          >
            {isDark ? <Sun className="w-4 h-4 text-white" /> : <Moon className="w-4 h-4 text-black" />}
          </button>

          <button
            onClick={() => handleNav('dashboard')}
            className={`p-2 rounded-lg border transition-colors ${
              activeScreen === 'dashboard'
                ? 'bg-neutral-900 text-white dark:bg-white dark:text-black border-neutral-900 dark:border-white'
                : 'bg-neutral-100 dark:bg-neutral-900 text-neutral-900 dark:text-white border-neutral-300 dark:border-neutral-700'
            }`}
            aria-label="Dashboard"
          >
            <LayoutDashboard className="w-4 h-4" />
          </button>

          <button
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            className="p-2 rounded-lg bg-neutral-100 dark:bg-neutral-900 border border-neutral-300 dark:border-neutral-700 text-neutral-900 dark:text-white"
            aria-label="Toggle Navigation Menu"
          >
            {mobileMenuOpen ? <X className="w-5 h-5" /> : <Menu className="w-5 h-5" />}
          </button>
        </div>
      </div>

      {/* Mobile Menu Dropdown */}
      {mobileMenuOpen && (
        <div className="xl:hidden bg-white dark:bg-black border-b border-neutral-200 dark:border-neutral-800 px-4 pt-2 pb-6 space-y-1">
          {navLinks.map((link) => {
            const isActive = activeScreen === link.screen;
            return (
              <button
                key={link.screen}
                onClick={() => handleNav(link.screen)}
                className={`w-full text-left px-4 py-3 rounded-lg text-sm font-semibold transition-colors ${
                  isActive
                    ? 'bg-neutral-900 text-white dark:bg-white dark:text-black border border-neutral-900 dark:border-white'
                    : 'text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-900'
                }`}
              >
                {link.name}
              </button>
            );
          })}
        </div>
      )}
    </nav>
  );
}
